return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n >= 2 && n <= 4) ? 1 : 2);','language'=>'sk_SK','project-id-version'=>'Plugins - Kybernaut IČO DIČ - Stable (latest release)','pot-creation-date'=>'2026-10-25T18:01:39+00:00','po-revision-date'=>'2026-10-25T21:38:13+00:00','x-generator'=>'GlotPress/4.1.0','messages'=>['Adds Czech Company & VAT numbers (IČO & DIČ) to WooCommerce billing fields and verifies if data are correct.'=>'Pridá IČO a DIČ do formulára s fakturačnou adresou vo WooCommerce a overí, či sú zadané hodnoty skutočné.','View GitHub'=>'Zobraziť GitHub','GitHub'=>'GitHub','Write a Review'=>'Ohodnotiť','View Kybernaut IČO DIČ settings'=>'Zobraziť nastavenia Kybernaut IČO DIČ','Settings'=>'Nastavenia','Business ID is invalid.'=>'IČO nie je platné.','Unexpected error occurred. Try it again.'=>'Nastala neočakávaná chyba. Vyskúšajte to znovu.','Clear company details'=>'Vymazať údaje o firme','Validating data in ARES.'=>'Overujem údaje v ARESe.','Information loaded succesfully from ARES.'=>'Informácie boli úspešne načítané z ARESu.','Validating data in Finančná správa.'=>'Overujem údaje vo Finančnej správe.','Information loaded succesfully from Finančná správa.'=>'Informácie boli úspešne načítané z Finančnej správy.','Validating data in %s.'=>'Overujem údaje v registri %s.','Information loaded successfully from %s.'=>'Informácie boli úspešne načítané z registra %s.','Turn on "%s" first.'=>'Najprv zapnite „%s“.','CZ: Validate Business ID in ARES'=>'CZ: Overiť IČO v ARESe','SK: Validate in Finančná správa'=>'SK: Overiť vo Finančnej správe','Turn on at least one of the ARES, Finančná správa or VIES checks first.'=>'Najprv zapnite aspoň jednu z kontrol v ARES, Finančnej správe alebo VIES.','Buying as a company'=>'Nakupujem na firmu','Reverse charge: the order is without VAT, the buyer accounts for it.'=>'Prenesenie daňovej povinnosti: objednávka je bez DPH, DPH odvedie odberateľ.','This tax number is valid. Without the country code (%s) it is not an EU VAT ID, so the order is placed with VAT.'=>'Toto daňové číslo je platné. Bez kódu krajiny (%s) nie je IČ DPH v EÚ, objednávka sa preto vytvorí s DPH.','This %s is not registered for VAT in the EU (VIES), so the order is placed with VAT.'=>'Toto %s nie je registrované pre DPH v EÚ (VIES), objednávka sa preto vytvorí s DPH.','Business ID'=>'IČO','Tax ID'=>'DIČ','VAT reg. no.'=>'IČ DPH ','Czech DIČ fieldVAT ID'=>'DIČ','EU VAT number fieldVAT ID'=>'IČ DPH','Slovak IČ DPH fieldVAT ID'=>'IČ DPH','optional, only if you are a VAT payer'=>'voliteľné, len ak ste platca DPH','label before a value%s: '=>'%s: ','Verification of VAT number has failed.'=>'Overenie IČ DPH zlyhalo.','Caution!'=>'Pozor!','Please, make sure the VAT number is valid before processing the order.'=>'Pred spracovaním objednávky sa uistite, že IČ DPH je platné.','Business ID not set.'=>'IČO nie je vyplnené.','Business ID must be a number and 8 digits long.'=>'IČO musí byť číslo s 8 číslicami.','An error occured while connecting to ARES, try it again later.'=>'Pri pripájaní k ARES nastala chyba, skúste to neskôr.','Entity doesn\'t exist in ARES.'=>'Uvedené IČO neexistuje v ARESe.','ARES is not responding.'=>'ARES neodpovedá.','Finančná správa lists are not available.'=>'Zoznamy Finančnej správy nie sú dostupné.','Business ID not found in Finančná správa, fill in the details manually.'=>'IČO sa vo Finančnej správe nenašlo, vyplňte údaje ručne.','Kybernaut IČO DIČ: the Finančná správa DIČ / IČ DPH lists are missing or older than a week, so those numbers cannot be validated. The import runs daily through WP-Cron (or run "wp woolab-icdic sk-import"); failures are logged in WooCommerce → Status → Logs.'=>'Kybernaut IČO DIČ: zoznamy DIČ / IČ DPH Finančnej správy chýbajú alebo sú staršie ako týždeň, preto tieto čísla nemožno overiť. Import beží denne cez WP-Cron (alebo spustite „wp woolab-icdic sk-import“); chyby sa zapisujú do WooCommerce → Stav → Záznamy.','Kybernaut IČO DIČ: the Finančná správa DIČ / IČ DPH lists cannot be imported, the zip, xmlreader and pdo_sqlite PHP extensions are required (ask your hosting).'=>'Kybernaut IČO DIČ: zoznamy DIČ / IČ DPH Finančnej správy nemožno importovať, sú potrebné PHP rozšírenia zip, xmlreader a pdo_sqlite (opýtajte sa svojho poskytovateľa hostingu).','Import status'=>'Stav importu','This feature is not compatible with Fluid Checkout for WooCommerce.'=>'Táto funkcia nie je kompatibilná s pluginom Fluid Checkout for WooCommerce.','Kybernaut IČO DIČ options'=>'Nastavenia Kybernaut IČO DIČ','The following options affect how Business ID and VAT number behaves.'=>'Nasledujúce možnosti ovplyvnia ako sa bude správať overovanie IČO a DIČ.','Toggle fields visibility'=>'Viditeľnosť polí','Enable toggle switch to show/hide input fields'=>'Povoliť prepínač na zobrazenie/skrytie polí IČO, DIČ a Firma','Move Country to top'=>'Presunúť pole "Krajina" na začiatok','Move Country field above the "Buying as a company" toggle'=>'Presunúť pole "Krajina" nad zaškrtávacie pole "Nakupujem na firmu"','Company fields'=>'Firemné polia','The company name and the Business ID (in the Czech Republic and Slovakia, where every company has one). "Required for companies" works best with the toggle: without it, a filled-in company name makes the customer a company. The DIČ of the shop\'s own country follows it only with "Require DIČ". The VAT ID stays optional, abroad with "only if you are a VAT payer".'=>'Názov firmy a IČO (v Česku a na Slovensku, kde ho má každá firma). „Povinné pre firmy“ funguje najlepšie s prepínačom: bez neho robí zo zákazníka firmu vyplnený názov firmy. DIČ krajiny obchodu sa týmto nastavením riadi len so zapnutým „Vyžadovať DIČ“. IČ DPH zostáva voliteľné, pri zahraničných firmách s „len ak ste platca DPH“.','Optional: "(optional)", as WooCommerce marks fields'=>'Voliteľné: „(voliteľné)“, ako polia označuje WooCommerce','No mark: like any other field'=>'Bez označenia: ako každé iné pole','Asterisk: marked required, the order goes through without them'=>'Hviezdička: označené ako povinné, objednávka prejde aj bez nich','Required for companies: no order without them (recommended)'=>'Povinné pre firmy: bez nich objednávka neprejde (odporúčané)','Require DIČ'=>'Vyžadovať DIČ','A company from the shop\'s own country that enters its IČO has to enter its DIČ too, and "Required for companies" asks for it. Off by default: non-profit organizations may have an IČO but no DIČ.'=>'Firma z krajiny obchodu, ktorá zadá IČO, musí zadať aj DIČ, a „Povinné pre firmy“ ho vyžaduje. Predvolene vypnuté: neziskové organizácie môžu mať IČO, ale nie DIČ.','Enable validation of VAT number in EU database VIES.'=>'Povoliť overenie hodnoty IČ DPH v európskej databáze VIES.','Enable VAT exemption for valid EU VAT numbers'=>'Povoliť oslobodenie od DPH pre platné európske IČ DPH','To enable this feature, turn on taxes in your store.'=>'Pre povolenie zapnite dane vo svojom obchode.','To enable this feature, set your base country to one of the EU VAT countries.'=>'Pre povolenie nastavte krajinu obchodu na jednu z krajín EÚ.','Check Business ID, DIČ and IČ DPH in the Finančná správa lists, downloaded daily (about 70 MB) into a SQLite file in the uploads folder (about 190 MB). Business IDs not in the lists yet (new, or not registered for tax) are accepted without autofill. IČ DPH is checked in VIES only when the lists do not have it.'=>'Overiť IČO, DIČ a IČ DPH v zoznamoch Finančnej správy, ktoré sa denne sťahujú (asi 70 MB) do SQLite súboru v priečinku uploads (asi 190 MB). IČO, ktoré v zoznamoch ešte nie je (nová firma alebo neregistrovaná na daň), sa prijme bez automatického vyplnenia. IČ DPH sa overuje vo VIES, len ak ho zoznamy neobsahujú.','Czech Republic'=>'Česko','Enable validation of Business ID in Czech database ARES.'=>'Povoliť overenie hodnoty IČO v databáze ARES.','CZ: Validate and autofill based on ARES'=>'CZ: Overiť a automaticky vyplniť podľa ARES','Enable company name search, and autofill and validation for Company, VAT number, Address, City, and Postcode fields based on Czech database ARES. Requires checked the option above.'=>'Povoliť vyhľadávanie podľa názvu firmy a automatické vyplnenie a overenie polí Firma, DIČ, Adresa, Mesto a PSČ podľa českej databázy ARES. Vyžaduje zapnutú voľbu vyššie.','Slovakia'=>'Slovensko','SK: Validate and autofill based on Finančná správa'=>'SK: Overiť a automaticky vyplniť podľa Finančnej správy','Enable company name search, and autofill and validation for Company, DIČ, IČ DPH, Address, City, and Postcode fields. Requires checked the option above.'=>'Povoliť vyhľadávanie podľa názvu firmy a automatické vyplnenie a overenie polí Firma, DIČ, IČ DPH, Adresa, Mesto a PSČ. Vyžaduje zapnutú voľbu vyššie.','SK: Disable DIČ / IČ DPH match check'=>'SK: Vypnúť kontrolu zhody DIČ / IČ DPH','Disable validation that IČ DPH must equal "SK" + DIČ. Some non-profit organizations have IČ DPH that does not match their DIČ.'=>'Vypnúť kontrolu, že IČ DPH sa musí rovnať „SK“ + DIČ. Niektoré neziskové organizácie majú IČ DPH, ktoré nezodpovedá ich DIČ.','European Union'=>'Európska únia','EU: Validate VAT number in VIES'=>'EU: Overiť IČ DPH vo VIES','Business ID only where companies have one'=>'IČO len tam, kde ho firmy majú','Hide the Business ID field for billing countries other than Slovakia and the Czech Republic, whose companies have no IČO. The list can be changed with the woolab_icdic_ic_countries filter.'=>'Skryť pole IČO pre fakturačné krajiny okrem Slovenska a Česka, ktorých firmy IČO nemajú. Zoznam sa dá zmeniť filtrom woolab_icdic_ic_countries.','EU: VAT exempt'=>'EU: Oslobodenie od DPH','When a check fails'=>'Keď kontrola zlyhá','Ignore when ARES, Finančná správa or VIES check fails for technical reasons'=>'Ignorovať, keď overenie v ARES, vo Finančnej správe alebo vo VIES zlyhá z technických dôvodov','Allow the creation of an order if the verification of the Business ID in ARES or Finančná správa, or the VAT number in the European VIES database fails for technical reasons.'=>'Umožniť vytvorenie objednávky, ak sa z technických dôvodov nepodarí overiť IČO v ARES alebo vo Finančnej správe, alebo IČ DPH v európskej databáze VIES.','Leave empty to follow the theme.'=>'Nechajte prázdne, ak sa má použiť farba témy.','Status icons'=>'Stavové ikony','The padlock on the company name and Business ID after an autofill, and the checkmark on the other filled-in fields.'=>'Zámok pri názve firmy a IČO po automatickom vyplnení a fajka pri ostatných vyplnených poliach.','Verified'=>'Overené','Padlock and checkmark. Leave empty for green (#007518).'=>'Zámok a fajka. Nechajte prázdne pre zelenú (#007518).','Clear'=>'Vymazanie','The X the padlock turns into. Leave empty for red (#a00).'=>'X, na ktoré sa zmení zámok. Nechajte prázdne pre červenú (#a00).','Company name suggestions'=>'Návrhy názvov firiem','By default the list takes its colours from the company field.'=>'Predvolene preberá zoznam farby z poľa s názvom firmy.','Background'=>'Pozadie','Text'=>'Text','Border'=>'Okraj','Highlighted suggestion'=>'Zvýraznený návrh','Leave empty for a tint of the text colour.'=>'Nechajte prázdne pre odtieň farby textu.','Corner radius'=>'Zaoblenie rohov','In pixels. Leave empty for the company field\'s own.'=>'V pixeloch. Nechajte prázdne pre zaoblenie poľa s názvom firmy.','Finančná správa lists'=>'Zoznamy Finančnej správy','The DIČ and IČ DPH lists the Slovak checks run against, imported daily.'=>'Zoznamy DIČ a IČ DPH, podľa ktorých sa overujú slovenské údaje, importované denne.','%1$s (%2$s ago)'=>'%1$s (uplynulo: %2$s)','Off. Enable "SK: Validate in Finančná správa" in %s.'=>'Vypnuté. Zapnite „SK: Overiť vo Finančnej správe“ v časti %s.','Validation'=>'Overovanie','Up to date'=>'Aktuálne','Older than a week: Slovak numbers are checked in VIES only, or let through when "ignore when the check fails" is on.'=>'Staršie ako týždeň: slovenské čísla sa overujú len vo VIES, alebo sa prijmú, ak je zapnuté „ignorovať, keď overenie zlyhá“.','Not imported yet'=>'Zatiaľ neimportované','Status'=>'Stav','Last import'=>'Posledný import','%1$s DIČ, %2$s IČ DPH'=>'%1$s DIČ, %2$s IČ DPH','Database'=>'Databáza','The file is missing, the next import creates it again.'=>'Súbor chýba, najbližší import ho vytvorí znova.','Last failed import'=>'Posledný neúspešný import','Not scheduled, it is scheduled again on the next page load.'=>'Nenaplánované, naplánuje sa znova pri najbližšom načítaní stránky.','%s, overdue: WP-Cron has not run since. It runs on page visits, or set up a server cron job for wp-cron.php.'=>'%s, oneskorené: WP-Cron odvtedy nebežal. Spúšťa sa pri návštevách stránky, alebo nastavte serverový cron pre wp-cron.php.','Next import'=>'Ďalší import','PHP extensions'=>'Rozšírenia PHP','Import now'=>'Importovať teraz','Every import is logged in %s.'=>'Každý import sa zapisuje do %s.','WooCommerce → Status → Logs'=>'WooCommerce → Stav → Záznamy','Set by the %s filter in the theme or a plugin.'=>'Nastavené filtrom %s v téme alebo v plugine.','IČO DIČ'=>'IČO DIČ','Appearance'=>'Vzhľad','Finančná správa'=>'Finančná správa','Enter a valid Business ID'=>'Zadajte platnú hodnotu IČO.','%1$s is not corresponding to %2$s.'=>'%1$s nezodpovedá údajom v registri %2$s.' . "\0" . '%1$s nezodpovedajú údajom v registri %2$s.' . "\0" . '%1$s nezodpovedajú údajom v registri %2$s.','%s is not corresponding to Finančná správa.'=>'%s nezodpovedá údajom Finančnej správy.' . "\0" . '%s nezodpovedajú údajom Finančnej správy.' . "\0" . '%s nezodpovedajú údajom Finančnej správy.','%s is not corresponding to ARES.'=>'%s nezodpovedá hodnotám uvedeným v ARESe.' . "\0" . '%s nezodpovedajú hodnotám uvedeným v ARESe.' . "\0" . '%s nezodpovedajú hodnotám uvedeným v ARESe.','field labelThe billing country does not correspond to the country of the %s.'=>'Fakturačná krajina nezodpovedá krajine, ktorá vydala %s.','field labelThe shipping country does not correspond to the country of the %s.'=>'Krajina doručenia nezodpovedá krajine, ktorá vydala %s.','field label%s has not a correct format.'=>'%s nemá správny formát.','field labelEnter a valid %s.'=>'Zadajte platné %s.','field labelCould not validate %s.'=>'%s sa nepodarilo overiť.','%1$s or %2$s is not valid.'=>'%1$s alebo %2$s nie je platné.','Tax ID does not belong to the entered Business ID.'=>'DIČ nepatrí k zadanému IČO.','Could not validate Tax ID.'=>'DIČ sa nepodarilo overiť.']];